import{z as i,x as A,o as r,c,q as s,j as l,D as o,d as t,s as d,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"原子读改写","description":"","frontmatter":{"title":"原子读改写","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/atomic-rmw.md","filePath":"cs/atomic-rmw.md","lastUpdated":1791063341000}'),B={name:"cs/atomic-rmw.md"};function p(m,a,h,D,f,u){const E=A("Mermaid");return r(),c("div",null,[a[2]||(a[2]=s('<h1 id="原子读改写" tabindex="-1">原子读改写 <a class="header-anchor" href="#原子读改写" aria-label="Permalink to &quot;原子读改写&quot;">​</a></h1><div class="epigraph"><p>测试并置位、比较并交换、取并加，把「读—改—写」收成一条对总线可见的操作；没有它，锁字本身会竞争。</p><footer>—— 据 Dijkstra 之后的硬件实践；Love, Linux Kernel Development 整理</footer></div><p><a href="/cs/memory-barrier-os">上一课</a>钉住可见序，但锁字的「若为 0 则置 1」仍是两条访存，中间可被他核切开。<a href="/cs/race-critical">竞争</a> 的计数器例子正是这种切开。缺口是硬件 <strong>RMW 原子</strong>：<code>swap</code>、<code>cmpxchg</code>、<code>fetch_add</code>，在缓存一致性协议下对该地址表现为不可分。本课只钉对象，不写微架构延迟表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纯软件 Peterson 在 SC 上可互斥，在放宽模型加编译器下脆弱。内核与用户运行时默认用原子指令做锁与引用计数。缺口不是再讲 fence 的分类，而是：<strong>哪一类更新必须是 RMW</strong>——锁字、引用计数、无锁链表的头指针。失败的 CAS 还给出无锁算法的循环，后课再收。</p><p><span class="marginnote">RMW 通常对同一 cache 行上锁（MESI 的 M），他核要等行转手。这就是自旋锁缓存行乒乓的来源。</span></p><p><span class="marginnote">数字实例：5 个线程各给引用计数加 1，若读改写被切开，两个线程可能同时读到 6、各自写回 7，最终得 7 而不是 10。计数少了就提前释放，正好砸向还在使用的对象——use-after-free 的一种生成方式就这么朴素。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>test_and_set</code>：读旧值并置 1，返回旧值，用来做最简自旋。<code>fetch_add</code>：引用计数。<code>cmpxchg</code>：期望值匹配才写成新值，否则返回当前。内核把它们包成 <code>atomic_t</code> 与 <code>atomic_long</code>，并规定是否自带屏障。本课不把每种 ISA 的 <code>lock</code> 前缀写完。</p>',9)),(r(),l(n,null,{default:o(()=>[d(E,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20RMW%5B%22%E5%8E%9F%E5%AD%90%E8%AF%BB%E6%94%B9%E5%86%99%22%5D%20--%3E%20TAS%5B%22%E6%B5%8B%E8%AF%95%E5%B9%B6%E7%BD%AE%E4%BD%8D%3A%20%E9%94%81%22%5D%0A%20%20RMW%20--%3E%20ADD%5B%22%E5%8F%96%E5%B9%B6%E5%8A%A0%3A%20%E8%AE%A1%E6%95%B0%22%5D%0A%20%20RMW%20--%3E%20CAS%5B%22CAS%3A%20%E6%9D%A1%E4%BB%B6%E6%9B%B4%E6%96%B0%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[t("单核关中断可以代替短 RMW，但挡不住多核；"),e("a",{href:"/cs/lock-irq"},"锁与关中断"),t(" 下一课把两者搭配。")],-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},[t("直觉类比："),e("code",null,"fetch_add"),t(" 像柜台叫号机——按一下（原子加），机器吐给你一个唯一旧值当号牌，两个人绝不可能拿到同一个号；普通「看一眼当前号、自己心里 +1 再写回去」就必然撞号，这正是丢失更新。")])],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"原子性相对的是该地址上的其它访存，不是全内存全序——全序仍要屏障。CAS 的「成功」只说明这一刻值匹配，不说明指针所指对象没被回收，那是 ABA，更后一课。引用计数用 fetch_add 避免丢失更新，仍要配对的屏障才能与对象内容同步。",-1)),a[7]||(a[7]=e("p",null,"切开的读改写怎么丢更新，一条原子怎么保住：",-1)),(r(),l(n,null,{default:o(()=>[d(E,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20BAD%5B%22%E6%99%AE%E9%80%9A%20%E8%AF%BB%20%E5%86%8D%20%E5%86%99%20%E4%B8%A4%E6%9D%A1%E6%8C%87%E4%BB%A4%22%5D%0A%20%20%20%20B1%5B%22%E6%A0%B8%201%20%E8%AF%BB%E5%88%B0%205%22%5D%20--%3E%20B2%5B%22%E6%A0%B8%202%20%E4%B9%9F%E8%AF%BB%E5%88%B0%205%22%5D%20--%3E%20B3%5B%22%E5%90%84%E8%87%AA%E5%86%99%E5%9B%9E%206%20%E7%99%BD%E5%8A%A0%E4%B8%80%E6%AC%A1%22%5D%0A%20%20end%0A%20%20subgraph%20GOOD%5B%22fetch_add%20%E4%B8%80%E6%9D%A1%E5%8E%9F%E5%AD%90%22%5D%0A%20%20%20%20G1%5B%22%E6%A0%B8%201%20%E5%8E%9F%E5%AD%90%E5%8A%A0%20%E8%BF%94%E5%9B%9E%E6%97%A7%E5%80%BC%205%22%5D%20--%3E%20G2%5B%22%E6%A0%B8%202%20%E5%8E%9F%E5%AD%90%E5%8A%A0%20%E6%8E%92%E9%98%9F%E5%90%8E%E6%89%A7%E8%A1%8C%20%E7%BB%93%E6%9E%9C%207%22%5D%0A%20%20end%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 LL/SC 的伪失败与循环重试的全部细节，只承认有的 ISA 用 LL/SC 模拟 CAS。也不把业务逻辑写成「一条 CAS 事务」。用户态关中断不能代替 RMW：那是特权。</p><p><span class="marginnote">常见误区：初学者容易把「原子」听成「事务」。一条 CAS 只保住一个地址的一次更新；「查余额、扣款、记账」这类多步逻辑的整体原子性要靠锁或真事务包住，硬塞进一条 CAS 是无锁算法课里最贵的坑。</span></p><p>后课默认：锁字用原子 RMW 更新。内核里还要决定是否关本地 IRQ，下一课<a href="/cs/lock-irq">锁与关中断</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RMW 让锁字与计数的读改写不可切。</li><li>CAS/TAS/fetch_add 是三类常用形态；跨核仍碰 cache 行。</li><li>与 IRQ 的搭配是下一课。</li><li>出处：Love, <em>LKD</em>；Silberschatz et al., <em>OSC</em>。</li></ul>',6))])}const C=i(B,[["render",p]]);export{S as __pageData,C as default};
